  "admin.accounts.signupsNote": "Applies to registration and to first-time Discord sign-ins alike. Existing users always keep their access.",
  "admin.accounts.whoStarts": "Who may start campaigns and workshops",
  "admin.accounts.startEveryone": "Everyone with an account",
  "admin.accounts.startAdmins": "Administrators only: others join by room code",
  "admin.accounts.paidAi": "Paid AI backends",
  "admin.accounts.paidAiHint": "Paid means a text, picture or speech backend on a public host that takes this server's key (OpenAI, OpenRouter, a hosted model), and the agent program. Backends on this machine or your network (llama-server, Ollama, ComfyUI, Kokoro, Whisper) stay open to every table, keyed or not. A table that may not spend the paid ones can bring its own key in the client app.",
  "admin.accounts.paidEveryone": "Every campaign may use them",
  "admin.accounts.paidAdmins": "Only campaigns an administrator leads",
  "admin.accounts.grace": "Account deletion grace period (days)",
  "admin.accounts.graceHint": "When someone deletes their account it is signed out at once and erased after this many days; signing in before then keeps it. 0 erases immediately. Deleting a user from the Users tab always erases at once.",
  "admin.accounts.days": "days",
  "admin.accounts.rolled": "Rolled 4d6 stats",
  "admin.accounts.rolledHint": "The server throws and keeps a player's six 4d6 totals. Choose whether they may throw again: never, only when the six add up to less than a total you set (70 is the default; the book names no rule), or as often as they like. This is the rule in the library and at every table that follows the server, where a player has one six for all of them. A table can set its own rule in its settings and then keeps a separate six for each player; a character made there still joins its player's library like any other, and a library character or a file brought to a table is only checked against what the dice could give.",
  "admin.accounts.rolled.first": "The first roll stands",
  "admin.accounts.rolled.low": "Reroll a low roll",
  "admin.accounts.rolled.free": "Reroll as often as they like",
  "admin.accounts.rolledBelow": "Reroll when the six add up to less than",
  "admin.accounts.total": "total",
