  "admin.addons.heading": "Addons",
  "admin.addons.intro": "An addon is a program that runs beside this server and adds to what it can do: reading a rulebook PDF into a workshop, building a battle map with 3D tools, drawing the board another way. Addons only reach the app through the doors it opens for them, and what they make is checked by the same rules as everything else.",
