  "narrator.noService": "This server has no speech service yet, so nothing is read aloud. Ask the server owner to set one up; the campaign can turn narration on from its Table settings afterwards.",
  "narrator.voiceLabel": "Narrator voice",
  "narrator.pace": "Pace",
  "narrator.paceLabel": "Narrator pace",
  "narrator.whoLabel": "Character voices",
  "narrator.whoTitle": "Who voices the characters?",
  "narrator.readThem": "The narrator reads them",
  "narrator.readThemHint": "Until you give a character a voice of their own",
  "narrator.eachVoice": "Each speaker gets a voice",
  "narrator.eachVoiceHint": "Cast from this server's voices as they first speak, then kept",
  "narrator.eachNote": "Anyone who speaks is given a voice the first time they do and keeps it. ",
  "narrator.readNote": "Speakers without a voice of their own are read by the narrator. ",
  "narrator.changeLater": "Change any character's voice later in {place}.",
  "narrator.offNote": "Narration is off, so nothing is read aloud. The narrator and character voice choices are kept for when it is turned on.",
  "narrator.allies": "AI allies",
  "narrator.alliesSolo": "Party members travel with you until dismissed; guests are allies who show up for a scene or a battle and then leave.",
  "narrator.alliesTable": "Guests are friendly NPCs the GM brings in for a scene or a battle; they fight with real stats and leave when the fight ends. Party members stay until dismissed.",
  "narrator.partyAtOnce": "Party members at once",
  "narrator.guestsAtOnce": "Guests at once",
  "creator.info.casting": "Two choices decide who reads a line aloud.\n\n**The narrator's voice and pace** read the story, and every speaker who has no voice of their own.\n\n**Character voices** belong to one speaker each. With *Each speaker gets a voice*, everyone who speaks (an innkeeper, a monster, a companion) is given one of this server's voices the first time they talk and keeps it from then on. With *The narrator reads them*, nobody is given one automatically, and any voice you do give a character still plays.\n\nEither way, a voice can be given or changed per character once the campaign has people in it: the Character voices list in Table settings (Narration and character voices), in the lobby or the table's Settings tab. Each player can also choose the voice their own character speaks in there.\n\nThis is the table's spoken narration. Live voice chat between players is a separate setting.",
  "creator.casting.place": "the Character voices list in Table settings (Narration and character voices), in the lobby or the table's Settings tab",

