  "admin.voice.heading": "Voice chat",
  "admin.voice.intro.a": "Lets a table talk over live audio. Needs two things beyond this switch: the app reached over ",
  "admin.voice.intro.b": " (browsers block microphone access on plain http, except on localhost), and ",
  "admin.voice.intro.port": "one open port",
  "admin.voice.intro.c": " for both UDP and TCP. That port carries the audio itself, which is not HTTP and cannot go through a reverse proxy, so open it on your firewall pointing straight at this host.",
