  "admin.voice.domain": "Voice domain (optional)",
  "admin.voice.domainHint": "Announce a hostname instead of the IP. It must resolve straight here: a Cloudflare-proxied name does not carry UDP, so calls would connect and stay silent.",
  "admin.voice.unroutable": "Voice will connect but stay silent for remote players: set an announced address or domain.",
  "admin.voice.applyNote": "Port and address changes apply the next time somebody joins a call, once nobody is connected. No server restart needed.",
  "admin.discord.heading": "Discord sign-in",
  "admin.discord.intro.a": "Optional. Create an application at discord.com/developers, add the redirect URI ",
  "admin.discord.intro.b": " (the exact address players use, e.g. https://your.domain or http://lan-host:3005), then paste the client ID and secret. The login button appears once both are set. Behind a reverse proxy, also set the Public URL in the Server section above.",
  "admin.discord.clientId": "Client ID",
  "admin.discord.clientSecret": "Client secret",
  "admin.discord.secretEnv": "An env-var secret is also set.",
  "admin.discord.notSet": "Not set",
  "admin.playerAgents.loadAria": "Loading receiver addresses",
  "admin.playerAgents.intro": "A player can seat their own agent at a table and have it woken on its turn by a small receiver on their computer (Settings > Connected agents). This server sends only to the HTTPS addresses listed here. Add one only for a receiver you trust: it lets the server make requests to that host.",
  "admin.playerAgents.none": "No receiver addresses yet, so no player agent is sent a webhook.",
  "admin.playerAgents.fromEnv": "from ODM_PLAYER_WEBHOOK_ORIGINS",
  "admin.playerAgents.address": "Receiver address",
  "admin.playerAgents.allow": "Allow",
  "admin.playerAgents.poll": "Allow poll links",
  "admin.playerAgents.pollHint": "For an agent nothing can send requests to (a hosted assistant whose hooks can only check a URL): its player gets a secret link that says when their character has something to do. The server sends nothing; anyone holding the link can see that much. It stops when the player replaces or removes it or revokes the connection. Turning this off deletes every link.",
  "admin.playerAgents.saveFailed": "Could not save the player agent settings.",
  "admin.storage.loadAria": "Loading storage",
  "admin.storage.intro": "The story is kept forever: every message, roll, note, sheet, chapter snapshot and GM conversation. Once a day the server clears what nothing reads back (live updates older than a reconnecting page replays, prompt traces past a week, usage rows past 90 days merged by month with the same totals) and hands the space to the disk.",
