  "table.settings.world.packHint": "Pick a pre-built universe to rename races, classes, spells and monsters to fit it.",
  "table.settings.length.tip": "How far the GM plans the story ahead (acts, bosses, side quests). Changing it mid-campaign applies when the next saga is planned; any length continues with a sequel saga if you play past the finale.",
  "table.settings.length.short": "Short",
