  "table.settings.hp.short.rolled": "HP: rolled each level",
  "table.settings.hp.short.max": "HP: maximum each level",
  "table.settings.wealth.tip": "What a new character starts with: the class and background kit plus the background's coin, or gold the server rolls by class to buy gear with.",
  "table.settings.wealth.short.equipment": "Start: class kit and coin",
  "table.settings.wealth.short.rolled": "Start: rolled gold, buy gear",
  "table.settings.reroll.tip": "For 4d6 ability scores rolled at this table: whether a player may throw the six again, and when. The server rolls the dice either way. Following the server's rule, a player's six here are the ones they rolled in their library; with a rule of its own the table keeps a separate six for each player. A character made here still joins its player's library like any other, and characters brought from the library keep the scores they were made with.",
  "table.settings.stats": "Stats: {rule}",
