  "table.rules.variant.criticalFumbles.tip": "A natural 1 on an attack roll comes with a minor mishap the GM describes. Narration only: the server changes no numbers.",
  "table.rules.variant.encumbrance.label": "Encumbrance",
  "table.rules.variant.encumbrance.tip": "Carrying more than 5 times Strength in pounds slows a character by 10 feet.",
