  "table.rules.variant.lingeringInjuries.tip": "A critical hit or dropping to 0 HP can leave a lasting injury the GM describes. Narration only: the server tracks no injury and changes no numbers.",
  "table.rules.variant.powerfulCritical.label": "Powerful critical",
  "table.rules.variant.powerfulCritical.tip": "On a critical hit the extra weapon dice are dealt as their maximum instead of being rolled.",
  "table.rules.variant.criticalDamageMods.label": "Crit damage mods",
