  // The rulebook's own chrome (src/components/rulebook): the cover, the
  // frontispiece, the contents page, search, the page-turn and bookmark
  // tools, and the "how the table runs this" line. The book's pages
  // themselves (the SRD's body text, its titles and chapter blurbs in
  // srd-5.1.json) stay English; only the parts blurbs, the quick links and
  // the chrome around them are the interface's words.
  "rulebook.title": "The Rulebook",
  "rulebook.editionLine": "Fifth Edition · System Reference Document 5.1",
  "rulebook.fifthEdition": "Fifth Edition",
  "rulebook.openTheBook": "Open the book",
  "rulebook.contentsAria": "Contents and search",
  "rulebook.contents": "Contents",
  "rulebook.trouble.open": "The rulebook could not be opened just now.",
  "rulebook.trouble.retry": "Try again",
  "rulebook.trouble.page": "That page could not be found in the book.",
  "rulebook.prevPage": "Previous page",
  "rulebook.nextPage": "Next page",
  "rulebook.bookmark.add": "Bookmark this page",
  "rulebook.bookmark.remove": "Remove the bookmark",
  "rulebook.frontis.text1": "Every rule of the game in one volume: the races and classes, equipment, how to use ability scores, adventuring, combat, spellcasting, every spell, magic item and monster, and the conditions they inflict.",
  "rulebook.frontis.text2": "Three books are bound here: the players', the Game Master's and the monsters', each holding all that the reference document opens of the Player's Handbook, the Dungeon Master's Guide and the Monster Manual.",
