// ---- the option picker groups (usePickerGroups.ts) ----
  "builder.group.align.info":
    "Alignment is a two-word shorthand for how your character treats rules (lawful, neutral, chaotic) and other people (good, neutral, evil). It binds nothing: it is a note to yourself and to the GM about how this person tends to act, and characters drift over a campaign. Pick the one that sounds most like them and stop worrying about it.",
  "builder.group.align.LG": "Lawful Good",
  "builder.group.align.NG": "Neutral Good",
  "builder.group.align.CG": "Chaotic Good",
  "builder.group.align.LN": "Lawful Neutral",
  "builder.group.align.N": "True Neutral",
  "builder.group.align.CN": "Chaotic Neutral",
  "builder.group.align.LE": "Lawful Evil",
  "builder.group.align.NE": "Neutral Evil",
  "builder.group.align.CE": "Chaotic Evil",
  "builder.group.align.LG.blurb": "Does the right thing, by the rules. Keeps promises, protects the weak, trusts institutions to be worth defending. The paladin's default.",
  "builder.group.align.NG.blurb": "Does the most good available, law or no law. Helps whoever is in front of them without much regard for who is owed what.",
  "builder.group.align.CG.blurb": "Does the right thing, and breaks whatever rule is in the way. Rebels, smugglers with a conscience, people who free prisoners first and ask later.",
  "builder.group.align.LN.blurb": "Order for its own sake. The judge, the soldier, the monk: the code matters more than any one outcome it produces.",
  "builder.group.align.N.blurb": "No strong pull either way. Gets on with life, takes a side when a side has to be taken. The commonest alignment for ordinary people.",
  "builder.group.align.CN.blurb": "Freedom above all, their own most of all. Unpredictable but not cruel. Easy to play badly; check with your table before choosing it.",
  "builder.group.align.LE.blurb": "Takes what they want, within a system they respect and use. Tyrants, corrupt officials, devils. Keeps their word, which makes them worse.",
  "builder.group.align.NE.blurb": "Takes what they want and feels no need to dress it up. Loyal to nobody but themselves.",
  "builder.group.align.CE.blurb": "Destruction for its own sake. Almost always an NPC alignment; a party rarely survives one.",
  "builder.group.commonIn": "Common in {pack}",
  "builder.group.peoplesOf": "Peoples of {pack}",
  "builder.group.callingsOf": "Callings of {pack}",
  "builder.group.livesIn": "Lives in {pack}",
  "builder.group.allAlignments": "All alignments",
  "builder.group.allRaces": "All races",
  "builder.group.allClasses": "All classes",
  "builder.group.allBackgrounds": "All backgrounds",
  "builder.group.standardClasses": "Standard classes (5e Core Rules)",
  "builder.group.standardBackgrounds": "Standard backgrounds (5e Core Rules)",
